<template>
  <div class="operations-page">
    <header class="operations-heading"><div><router-link to="/dashboard" class="back-link">← 返回节点总览</router-link><h1>Agent 部署与远程连接</h1><p>检查节点连接，进入命令行，部署独立采集服务。</p></div><button v-if="authenticated" class="quiet-button" @click="logout">退出运维登录</button></header>
    <div v-if="!secure" class="transport-notice" role="alert"><strong>请通过 HTTPS 使用运维功能</strong><p>用户名、密码和命令行数据需要加密传输。</p><a :href="`https://${hostname}${route.fullPath}`">转到 HTTPS 页面 ↗</a></div>
    <form v-else-if="!authenticated" class="operator-login" @submit.prevent="login"><div class="login-mark">⌘</div><h2>运维登录</h2><p>输入运维口令后，可使用节点凭据连接和部署。登录有效期为 1 小时。</p><label for="operator-password">运维口令</label><input id="operator-password" v-model="operatorPassword" type="password" autocomplete="current-password" required maxlength="1024" placeholder="输入运维口令"><p v-if="error" class="operation-error" role="alert">{{ error }}</p><button class="primary-button" :disabled="loggingIn">{{ loggingIn ? '验证中…' : '登录运维控制台' }}</button></form>
    <template v-else>
      <div class="node-selector"><label for="ops-node">操作节点</label><select id="ops-node" v-model="selectedId" :disabled="job?.status === 'running'"><option value="">请选择节点</option><option v-for="s in servers" :key="s.id" :value="String(s.id)">{{ s.hostname }} · {{ s.ip_address }}:{{ s.ssh_port || 22 }}</option></select><span v-if="node" class="node-status" :class="node.status">{{ statusLabel(node.status) }}</span></div>
      <div v-if="node" class="operations-grid">
        <aside class="connection-panel">
          <div class="panel-caption"><span class="step-number">01</span><div><h2>连接身份</h2><p>{{ node.hostname }}</p></div><span class="mode-chip">{{ node.collection_mode === 'agent' ? 'Agent' : 'SSH' }}</span></div>
          <div class="connection-address"><span>目标地址</span><code>{{ node.ip_address }}:{{ node.ssh_port || 22 }}</code></div>
          <div class="credential-switch" role="group" aria-label="凭据来源"><button :class="{ selected: useSaved }" :disabled="!node.has_ssh_password || busy" @click="useSaved = true">已配置凭据</button><button :class="{ selected: !useSaved }" :disabled="busy" @click="useSaved = false">手动输入</button></div>
          <div v-if="useSaved" class="stored-credentials"><span class="saved-dot"/>使用 {{ node.ssh_user || 'root' }} 的已存密码<small>密码由服务端解密使用，不会返回浏览器。</small></div>
          <div v-else class="manual-credentials"><label>SSH 用户名<input v-model="credentials.username" autocomplete="off" maxlength="50" :disabled="busy"></label><label>SSH 密码<input v-model="credentials.password" type="password" autocomplete="new-password" maxlength="1024" placeholder="输入节点登录密码" :disabled="busy"></label><label class="save-checkbox"><input v-model="credentials.save" type="checkbox" :disabled="busy">验证成功后加密保存，供后续运维使用</label></div>
          <button class="test-button" :disabled="busy" @click="testConnection">{{ testing ? '正在检测…' : '检测 SSH 连通性' }} <span>↗</span></button>
          <div v-if="check" class="check-result" :class="{ success: check.ok, failure: !check.ok }" role="status"><strong>{{ check.ok ? '连接成功' : '连接未就绪' }}</strong><p>{{ check.message }}</p><small v-if="check.latency_ms">连接耗时 {{ check.latency_ms }} ms</small><code v-if="check.fingerprint">{{ check.fingerprint }}</code><template v-if="check.code === 'unknown_host'"><label class="trust-checkbox"><input v-model="trustConfirmed" type="checkbox">我已通过服务器控制台核对该指纹</label><button class="secondary-button" :disabled="!trustConfirmed || testing" @click="trustHost">保存信任并重新检测</button></template></div>
          <p class="connection-note">SSH 使用密码认证，不创建免密密钥。手动输入默认仅用于本次操作。</p>
        </aside>
        <main class="workspace-panel">
          <section class="deployment-panel"><div class="panel-caption"><span class="step-number">02</span><div><h2>部署独立 Agent</h2><p>每 5 分钟主动上报，保留节点及历史记录。</p></div></div><div class="deployment-summary"><div><span>上报入口</span><code>{{ reportEndpoint }}</code></div><div><span>运行方式</span><strong>独立运行包 · systemd 自动启动</strong></div></div><div class="deploy-actions"><span>自动检查 sudo、时钟、磁盘、证书和运行环境。</span><button class="primary-button" :disabled="busy" @click="deploy">{{ job?.status === 'running' ? '正在部署…' : deploying ? '准备部署…' : '一键部署 Agent' }}</button></div><div v-if="job" class="job-result" :class="job.status" role="status"><div class="job-caption"><strong>{{ job.status === 'running' ? '部署进行中' : job.status === 'success' ? '部署完成' : '需要检查' }}</strong><span>{{ job.message }}</span></div><pre class="deployment-log" aria-label="部署日志">{{ job.logs?.join('\n') || '任务已提交，正在等待检查结果…' }}</pre></div></section>
          <section class="terminal-panel"><div class="terminal-heading"><div><span class="terminal-indicator" :class="{ connected: terminalConnected }"/><h2>远程命令行</h2><span>{{ terminalConnected ? '已连接' : terminalConnecting ? '连接中…' : '未连接' }}</span></div><button v-if="terminalConnected || terminalConnecting" class="terminal-button" @click="disconnectTerminal">断开连接</button><button v-else class="terminal-button" :disabled="testing || deploying" @click="connectTerminal">进入命令行 ↗</button></div><div ref="terminalElement" class="terminal-canvas" :class="{ empty: !terminalStarted }"><div v-if="!terminalStarted" class="terminal-placeholder"><span>›_</span><strong>在浏览器中连接 {{ node.hostname }}</strong><p>支持常用命令、交互式程序和终端尺寸调整。</p></div></div><footer>连接随页面关闭而结束 · 闲置 15 分钟自动断开 · 命令和输出不写入项目日志</footer></section>
        </main>
      </div>
      <div v-else class="select-empty">选择一台节点开始检查、连接或部署。</div>
      <p v-if="error" class="operation-error page-error" role="alert">{{ error }}</p>
    </template>
  </div>
</template>
<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Terminal } from '@xterm/xterm'
import { FitAddon } from '@xterm/addon-fit'
import '@xterm/xterm/css/xterm.css'
import { api } from '../api'
import { useServers } from '../composables/useServers'
import { statusLabel } from '../utils/serverStatus'
const route=useRoute(),router=useRouter(),{servers,subscribe}=useServers()
const secure=location.protocol === 'https:',hostname=location.hostname
const authenticated=ref(false),operatorPassword=ref(''),loggingIn=ref(false),error=ref('')
const selectedId=ref(route.params.id || ''),useSaved=ref(false),credentials=ref({username:'',password:'',save:false})
const check=ref(null),trustConfirmed=ref(false),testing=ref(false),deploying=ref(false),job=ref(null)
const terminalElement=ref(null),terminalStarted=ref(false),terminalConnected=ref(false),terminalConnecting=ref(false)
const node=computed(() => servers.value.find(s => String(s.id) === selectedId.value))
const busy=computed(() => testing.value || deploying.value || job.value?.status === 'running')
const reportEndpoint=computed(() => node.value?.ip_address?.startsWith('192.168.1.') ? 'https://192.168.1.24/api/agent/report' : 'https://114.212.165.149:59443/api/agent/report')
let terminal,fit,observer,socket,pollTimer,polling=false,disposed=false,generation=0,autoCheckDone=false
const detail=e => typeof e.response?.data?.detail === 'string' ? e.response.data.detail : '操作失败，请检查网络和输入后重试。'
function handleError(e) { error.value=detail(e); if(e.response?.status === 401) { authenticated.value=false; disconnectTerminal(); stopPoll() } }
function payload() { return useSaved.value ? {use_saved:true} : {use_saved:false,username:credentials.value.username.trim(),password:credentials.value.password,save_credentials:credentials.value.save} }
function validInput() { if(!node.value) return false; if(!useSaved.value && (!credentials.value.username.trim() || !credentials.value.password)) {error.value='请填写 SSH 用户名和密码。';return false} return true }
async function login() { if(loggingIn.value) return; loggingIn.value=true;error.value='';try{await api.opsLogin(operatorPassword.value);authenticated.value=true;await loadJob();await maybeAutoCheck()}catch(e){handleError(e)}finally{operatorPassword.value='';loggingIn.value=false} }
async function logout() {try{await api.opsLogout()}finally{authenticated.value=false;operatorPassword.value='';credentials.value.password='';disconnectTerminal();stopPoll()} }
async function testConnection() {
  if(testing.value || !validInput()) return false
  testing.value=true;error.value='';trustConfirmed.value=false
  const current=generation
  try {const{data}=await api.sshTest(node.value.id,payload());if(disposed || current!==generation)return false;check.value=data;window.dispatchEvent(new CustomEvent('servers-refresh'));return data.ok}
  catch(e){if(current===generation)handleError(e);return false}finally{testing.value=false}
}
async function trustHost() {if(!trustConfirmed.value || !check.value?.fingerprint)return;try{await api.trustHost(node.value.id,check.value.fingerprint);await testConnection()}catch(e){handleError(e)} }
async function deploy() {
  if(busy.value || !validInput())return
  deploying.value=true;error.value=''
  try {if(!await testConnection())return;const{data}=await api.deployAgent(node.value.id,payload());job.value=data;credentials.value.password='';startPoll()}
  catch(e){handleError(e)}finally{deploying.value=false}
}
function stopPoll(){clearInterval(pollTimer);pollTimer=null}
function startPoll(){stopPoll();pollTimer=setInterval(pollJob,2000)}
async function pollJob(){if(polling || !job.value || disposed)return;polling=true;const id=job.value.id;try{const{data}=await api.deploymentJob(id);if(job.value?.id!==id)return;job.value=data;if(data.status!=='running'){stopPoll();window.dispatchEvent(new CustomEvent('servers-refresh'))}}catch(e){stopPoll();handleError(e)}finally{polling=false}}
async function loadJob(){if(!authenticated.value || !node.value)return;try{const{data}=await api.deploymentJobs(node.value.id);job.value=data.at(-1) || null;if(job.value?.status==='running')startPoll()}catch(e){handleError(e)}}
async function maybeAutoCheck(){if(!autoCheckDone && route.query.action==='check' && authenticated.value && node.value?.has_ssh_password){autoCheckDone=true;await testConnection()}}
function sendResize(){if(socket?.readyState===WebSocket.OPEN && terminalConnected.value && terminal)socket.send(JSON.stringify({type:'resize',cols:Math.max(20,Math.min(300,terminal.cols)),rows:Math.max(5,Math.min(100,terminal.rows))}))}
function disconnectTerminal(){if(socket){socket.onclose=null;socket.close();socket=null}observer?.disconnect();observer=null;terminal?.dispose();terminal=null;fit=null;terminalConnected.value=false;terminalConnecting.value=false;terminalStarted.value=false}
async function connectTerminal(){
  if(terminalConnecting.value || !validInput())return
  error.value='';disconnectTerminal();terminalConnecting.value=true;terminalStarted.value=true
  const current=generation
  await nextTick()
  if(disposed || current!==generation || !terminalElement.value || !node.value)return
  terminal=new Terminal({cursorBlink:true,fontSize:13,fontFamily:'ui-monospace, SFMono-Regular, Consolas, monospace',scrollback:2000,disableStdin:true,theme:{background:'#111b2b',foreground:'#dbe5f3',cursor:'#60a5fa',selectionBackground:'#334867'}})
  fit=new FitAddon();terminal.loadAddon(fit);terminal.open(terminalElement.value);fit.fit()
  const ws=new WebSocket(`wss://${location.host}/api/ops/nodes/${node.value.id}/terminal`);socket=ws
  const auth=payload()
  ws.onopen=()=>{if(socket===ws){ws.send(JSON.stringify(auth));if(auth.password)auth.password=''}}
  ws.onmessage=event=>{if(socket!==ws)return;const data=JSON.parse(event.data);if(data.type==='connected'){terminalConnected.value=true;terminalConnecting.value=false;terminal.options.disableStdin=false;terminal.focus();sendResize();window.dispatchEvent(new CustomEvent('servers-refresh'))}else if(data.type==='output')terminal.write(data.data);else if(data.type==='error'){error.value=data.message;check.value=data;terminal.writeln(`\r\n[${data.message}]`)}else if(data.type==='closed')terminal.writeln(`\r\n[${data.message}]`)}
  ws.onerror=()=>{error.value='终端连接失败，请检查 HTTPS、运维登录和 SSH 凭据。'}
  ws.onclose=()=>{if(socket!==ws)return;terminalConnected.value=false;terminalConnecting.value=false;terminal.options.disableStdin=true;terminal.writeln('\r\n[连接已断开]');socket=null}
  terminal.onData(data=>{if(ws.readyState===WebSocket.OPEN && terminalConnected.value)for(let i=0;i<data.length;i+=4096)ws.send(JSON.stringify({type:'input',data:data.slice(i,i+4096)}))})
  observer=new ResizeObserver(()=>{try{fit?.fit();sendResize()}catch{}});observer.observe(terminalElement.value)
}
watch(selectedId,value=>{if(value && String(route.params.id || '')!==value)router.replace({path:`/nodes/${value}/agent`})})
watch(()=>route.params.id,id=>{selectedId.value=id || ''})
watch(()=>node.value?.id,async()=>{generation++;disconnectTerminal();stopPoll();job.value=null;check.value=null;error.value='';credentials.value={username:node.value?.ssh_user || 'root',password:'',save:false};useSaved.value=!!node.value?.has_ssh_password;autoCheckDone=false;await loadJob();await maybeAutoCheck()},{immediate:true})
watch([useSaved,()=>credentials.value.username,()=>credentials.value.password],()=>{check.value=null;trustConfirmed.value=false})
onMounted(async()=>{subscribe();if(secure){try{await api.opsSession();authenticated.value=true;await loadJob();await maybeAutoCheck()}catch(e){if(e.response?.status!==401)handleError(e)}}})
onBeforeUnmount(()=>{disposed=true;generation++;disconnectTerminal();stopPoll();operatorPassword.value='';credentials.value.password=''})
</script>
<style scoped>
