witch button{flex:1;padding:8px 5px;font-size:11px;border:0;border-radius:5px;background:transparent;color:#94a3b8;cursor:pointer}.credential-switch button.selected{color:#2563eb;background:#fff;box-shadow:0 1px 4px #0f172a10}.manual-credentials{display:grid;gap:16px;margin:20px 0}.manual-credentials>label{display:flex;flex-direction:column;gap:8px;font-size:12px;color:#64748b}.manual-credentials input:not([type=checkbox]),.operator-login input{height:40px;padding:10px 12px;border:1px solid #dbe3ee;border-radius:8px;font-size:13px;outline:none;width:100%;box-sizing:border-box}.manual-credentials input:focus,.operator-login input:focus{border-color:#60a5fa;box-shadow:0 0 0 3px #dbeafe70}.manual-credentials .save-checkbox{flex-direction:row;align-items:flex-start;line-height:1.7;font-size:10px}.save-checkbox input,.trust-checkbox input{accent-color:#2563eb;margin:3px 0 0}.stored-credentials{font-size:12px;line-height:1.8;color:#475569;margin:22px 0}.stored-credentials small{display:block;font-size:11px;color:#94a3b8;margin-top:6px}.saved-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#10b981;margin-right:7px}.test-button{display:flex;justify-content:space-between;width:100%;padding:11px 14px;border:1px solid #bfdbfe;border-radius:8px;background:#eff6ff;color:#2563eb;font-size:12px;font-weight:600;cursor:pointer}.connection-note{font-size:10px;color:#94a3b8;line-height:1.8;margin:17px 0 0}.check-result{border:1px solid #e2e8f0;background:#f8fafc;border-radius:9px;padding:13px;margin-top:16px;font-size:11px;line-height:1.7}.check-result strong{font-size:12px}.check-result.success{background:#f0fdf4;border-color:#bbf7d0;color:#166534}.check-result.failure{background:#fff7ed;border-color:#fed7aa;color:#9a3412}.check-result p{margin:5px 0}.check-result code{display:block;font-size:10px;word-break:break-all;padding-top:8px}.trust-checkbox{display:flex;align-items:flex-start;gap:7px;margin:12px 0}.secondary-button{padding:8px 12px;border:1px solid #cbd5e1;border-radius:6px;background:#fff;color:#475569;cursor:pointer;font-size:11px}.workspace-panel{display:grid;gap:20px;min-width:0}.deployment-summary{display:grid;gap:15px;background:#f8fafc;border-radius:9px;padding:17px 18px;margin-top:22px}.deployment-summary>div{display:flex;gap:20px;align-items:center}.deployment-summary span{font-size:11px;color:#94a3b8;min-width:55px}.deployment-summary strong{font-size:12px;font-weight:500;color:#475569}.deployment-summary code{font-size:11px;color:#475569;overflow-wrap:anywhere}.deploy-actions{display:flex;gap:18px;justify-content:space-between;align-items:center;margin-top:20px}.deploy-actions>span{font-size:11px;line-height:1.8;color:#94a3b8}.primary-button{background:#2563eb;color:#fff;border:1px solid #2563eb;padding:11px 17px;border-radius:8px;font-size:12px;font-weight:600;white-space:nowrap;cursor:pointer}.primary-button:hover{background:#1d4ed8}.job-result{border-top:1px solid #edf2f7;margin-top:22px;padding-top:18px}.job-caption{display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:11px;color:#94a3b8}.job-caption strong{font-size:12px;color:#2563eb}.job-result.success strong{color:#059669}.job-result.failed strong{color:#dc2626}.deployment-log{background:#f8fafc;border:1px solid #e3eaf2;border-radius:8px;padding:13px;font:11px/1.9 ui-monospace,monospace;color:#64748b;max-height:220px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;margin-bottom:0}.terminal-panel{border:1px solid #202f43;border-radius:15px;background:#111b2b;overflow:hidden}.terminal-heading{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:16px 20px;border-bottom:1px solid #223046;background:#162234}.terminal-heading>div{display:flex;align-items:center;gap:10px}.terminal-heading h2{font-size:13px;color:#dbe5f3;font-weight:500;margin:0}.terminal-heading>div>span:last-child{font-size:10px;color:#62768f}.terminal-indicator{width:6px;height:6px;border-radius:50%;background:#526278}.terminal-indicator.connected{background:#34d399;box-shadow:0 0 9px #34d39940}.terminal-button{border:1px solid #35465e;background:#1b2b41;color:#b9cce5;border-radius:7px;padding:7px 11px;font-size:11px;cursor:pointer}.terminal-canvas{height:350px;padding:14px 16px 4px;box-sizing:border-box}.terminal-canvas.empty{display:grid;place-items:center}.terminal-placeholder{text-align:center;color:#62768f}.terminal-placeholder>span{display:block;font:32px ui-monospace,monospace;color:#344a65;margin-bottom:18px}.terminal-placeholder strong{font-size:12px;font-weight:500;color:#8fa3bf}.terminal-placeholder p{font-size:11px;margin-top:10px}.terminal-panel footer{font-size:10px;color:#536a86;padding:12px 20px;border-top:1px solid #1b2b40}.operator-login{background:white;border:1px solid #e2e8f0;border-radius:18px;max-width:360px;margin:60px auto;padding:32px}.login-mark{display:grid;place-items:center;width:42px;height:42px;border:1px solid #dbeafe;border-radius:12px;background:#eff6ff;color:#2563eb;font-size:24px}.operator-login h2{font-size:19px;margin-top:22px}.operator-login p{font-size:12px;line-height:1.8;color:#94a3b8}.operator-login label{display:block;font-size:12px;color:#64748b;margin:23px 0 9px}.operator-login .primary-button{width:100%;margin-top:18px}.operation-error{font-size:12px!important;color:#be123c!important;line-height:1.8}.page-error{background:#fff1f2;border:1px solid #fecdd3;border-radius:9px;padding:12px 16px}.transport-notice{background:#fffbeb;border:1px solid #fde68a;border-radius:12px;padding:22px;color:#92400e;font-size:13px}.transport-notice a{color:#92400e}.select-empty{text-align:center;padding:80px;color:#94a3b8;font-size:13px}button:disabled{opacity:.5;cursor:not-allowed}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #93c5fd;outline-offset:3px}@media(max-width:1100px){.operations-page{padding:24px}.operations-grid{grid-template-columns:275px minmax(0,1fr)}.connection-panel,.deployment-panel{padding:18px}.deployment-summary>div{align-items:flex-start;gap:10px}.deploy-actions{flex-wrap:wrap}}@media(max-width:850px){.operations-grid{grid-template-columns:1fr}.operations-heading{align-items:flex-start;gap:12px}.operations-heading h1{font-size:21px}.node-selector{padding:12px}.terminal-heading{padding:14px}.terminal-canvas{height:300px}.operations-page{padding:20px 15px}.operator-login{margin:30px auto;padding:24px}.deployment-summary code{font-size:10px}}
</style>
